(async () => { const A = window.__CITY_APP, scene = A.scene, sun = A.lightingSystem.sunLight;
 const meas = async (n = 120) => { const ts = []; for (let i = 0; i < n + 15; i++) { await new Promise((r) => requestAnimationFrame(r)); ts.push(performance.now()); } const d = []; for (let i = 16; i < ts.length; i++) d.push(ts[i] - ts[i - 1]); d.sort((a, b) => a - b); return +d[d.length >> 1].toFixed(2); };
 const R = {}; const info = () => { const i = A.renderer.info; return i.render ? i.render.triangles : 0; };
 const group = (pred, key) => { const list = []; scene.traverse((o) => { if (o.isMesh && o.visible && pred(o)) list.push(o); }); return list; };
 const toggle = async (key, list) => { if (!list.length) { R[key] = null; return; } list.forEach((o) => { o.visible = false; }); R[key] = await meas(); list.forEach((o) => { o.visible = true; }); };
 R.base = await meas(); R.baseTris = info();
 sun.castShadow = false; R.noSunShadow = await meas(); sun.castShadow = true;
 const prox = scene.getObjectByName('ShadowProxies'); if (prox) { prox.visible = false; R.noStandIns = await meas(); prox.visible = true; }
 await toggle('noNearMassing', group((o) => /^MassingBuildings_/.test(o.name) && o.userData.massingTier === 0));
 await toggle('noMidMassing', group((o) => /^MassingBuildings_/.test(o.name) && o.userData.massingTier === 1));
 await toggle('noFarMassing', group((o) => /^MassingBuildings_/.test(o.name) && o.userData.massingTier === 2));
 await toggle('noRoofsNear', group((o) => o.name === 'HippedRoofsNear'));
 await toggle('noRoofsFar', group((o) => o.name === 'HippedRoofsFar'));
 await toggle('noRoofsTall', group((o) => o.name === 'HippedRoofsTall'));
 await toggle('noRoofsAny', group((o) => /^HippedRoofs/.test(o.name)));
 const bld = scene.getObjectByName('CityBuildings'); if (bld) { bld.visible = false; R.allBuildingsHidden = await meas(); bld.visible = true; }
 R.base2 = await meas(); return R; })()

